"""Lightweight JSON persistence for job status (survives engine restart for polling)."""

from __future__ import annotations

import json
import logging
import time
from pathlib import Path
from typing import Any

_log = logging.getLogger("transub_engine.job_store")


def _job_path(job_id: str) -> Path:
    from .paths import get_jobs_root

    safe = "".join(ch for ch in str(job_id) if ch.isalnum() or ch in "-_")[:64]
    return get_jobs_root() / f"{safe}.json"


def save_job_snapshot(job: Any) -> None:
    """Best-effort write of job metadata (not full event log / result cues)."""
    try:
        job_id = str(getattr(job, "id", "") or "")
        if not job_id:
            return
        payload = {
            "id": job_id,
            "status": getattr(job, "status", None),
            "createdAt": getattr(job, "created_at", None),
            "updatedAt": getattr(job, "updated_at", None),
            "error": getattr(job, "error", None),
            "request": _safe_request(getattr(job, "request", None)),
            "resultSummary": _result_summary(getattr(job, "result", None)),
            "eventCount": len(getattr(job, "events", None) or []),
            "savedAt": time.time(),
        }
        path = _job_path(job_id)
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception as err:
        _log.debug("save_job_snapshot failed: %s", err)


def delete_job_snapshot(job_id: str) -> None:
    try:
        path = _job_path(job_id)
        if path.is_file():
            path.unlink()
    except Exception:
        pass


def load_job_snapshot(job_id: str) -> dict[str, Any] | None:
    path = _job_path(job_id)
    if not path.is_file():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else None
    except Exception:
        return None


def list_job_snapshots(*, limit: int = 50) -> list[dict[str, Any]]:
    """List recent job snapshots from disk (newest first)."""
    from .paths import get_jobs_root

    root = get_jobs_root()
    rows: list[tuple[float, dict[str, Any]]] = []
    try:
        paths = list(root.glob("*.json"))
    except Exception:
        return []
    for path in paths:
        if path.name.endswith(".ckpt.json") or ".ckpt." in path.name:
            continue
        # Skip checkpoint files named {id}.ckpt.json — already excluded by glob *.json
        # but id.ckpt.json matches *.json — filter by suffix pattern
        if path.stem.endswith(".ckpt"):
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(data, dict) or not data.get("id"):
                continue
            ts = float(data.get("updatedAt") or data.get("savedAt") or data.get("createdAt") or 0)
            rows.append((ts, data))
        except Exception:
            continue
    rows.sort(key=lambda x: x[0], reverse=True)
    out: list[dict[str, Any]] = []
    for _, data in rows[: max(1, min(200, int(limit or 50)))]:
        out.append(
            {
                "id": data.get("id"),
                "status": data.get("status"),
                "createdAt": data.get("createdAt"),
                "updatedAt": data.get("updatedAt"),
                "error": data.get("error"),
                "request": data.get("request"),
                "resultSummary": data.get("resultSummary"),
                "eventCount": data.get("eventCount"),
            }
        )
    return out


def _safe_request(req: Any) -> dict[str, Any]:
    if not isinstance(req, dict):
        return {}
    keep = (
        "task",
        "mediaPath",
        "outputDir",
        "language",
        "asrModel",
        "mtModel",
        "subFormats",
        "device",
        "vad",
        "audio",
        "glossary",
        "beamSize",
        "batchId",
        "batchIndex",
        "batchTotal",
        "includeWords",
        "karaokeVtt",
        "releaseGpuAfter",
        "perfProfile",
        "wordTimestamps",
        "retranscribe",
    )
    return {k: req.get(k) for k in keep if k in req}


def _result_summary(result: Any) -> dict[str, Any] | None:
    if not isinstance(result, dict):
        return None
    cues = result.get("cues") if isinstance(result.get("cues"), dict) else {}
    return {
        "task": result.get("task"),
        "outputs": result.get("outputs"),
        "mtModel": result.get("mtModel"),
        "language": result.get("language"),
        "sourceCueCount": len(cues.get("source") or []) if isinstance(cues, dict) else None,
        "zhCueCount": len(cues.get("zh") or []) if isinstance(cues, dict) else None,
    }
